type View='overview'|'simulation'|'planning'|'routes'|'fleet'|'quality'|'settings';
const nav=[{id:'overview',label:'Centro de controle',icon:LayoutDashboard},{id:'simulation',label:'Laboratório de cenários',icon:FlaskConical},{id:'planning',label:'Programação de cargas',icon:CalendarDays},{id:'routes',label:'Rotas e galpões',icon:RouteIcon},{id:'fleet',label:'Gestão da frota',icon:Truck},{id:'quality',label:'Qualidade do transporte',icon:ShieldCheck},{id:'settings',label:'Regras da operação',icon:SlidersHorizontal}] as const;
