function Stat({label,value,unit,note,icon:Icon,tone='blue'}:{label:string;value:string|number;unit?:string;note:React.ReactNode;icon:React.ElementType;tone?:string}){return <article className="stat"><div className="stat-top"><span>{label}</span><Icon size={20}/></div><div className="stat-value">{value}<small>{unit}</small></div><div className={`stat-note ${tone}`}>{note}</div></article>}
function Nav({view,setView}:{view:View;setView:(v:View)=>void}){const {setOpenMobile}=useSidebar();return <Sidebar className="app-sidebar"><SidebarHeader className="brand"><img src="/favicon.svg" alt=""/><div>avialog<span>INTELIGÊNCIA DE TRANSPORTE</span></div></SidebarHeader><SidebarContent><div className="workspace-switch"><span className="workspace-icon"><Warehouse size={19}/></span><div>Trans Brasília<small>Central de planejamento</small></div><ChevronRight size={15}/></div><p className="nav-caption">OPERAÇÃO</p><SidebarMenu className="nav-menu">{nav.map(({id,label,icon:Icon})=><SidebarMenuItem key={id}><SidebarMenuButton isActive={view===id} className="nav-button" onClick={()=>{setView(id);setOpenMobile(false)}}><Icon/><span>{label}</span>{id==='simulation'&&<small className="nav-new">SIM</small>}</SidebarMenuButton></SidebarMenuItem>)}</SidebarMenu><div className="sidebar-note"><div><Sparkles size={17}/>Decisões com contexto</div><p>Compare cenários e acompanhe cada carga, da origem ao retorno.</p><button onClick={()=>setView('simulation')}>Explorar simulador <ChevronRight size={14}/></button></div></SidebarContent><SidebarFooter className="profile"><div className="avatar">DA</div><div>Central de análise<small>Ambiente de planejamento</small></div><ShieldCheck size={17}/></SidebarFooter></Sidebar>}
function OccupancyChart({result,cursor,onCursor}:{result:Result;cursor:number;onCursor:(v:number)=>void}){const max=Math.max(result.active,1);const coords=result.hourly.map((v,i)=>`${42+i*27.2},${178-v.busy/max*130}`);const line='M'+coords.join(' L');return <div className="occupancy-chart"><svg viewBox="0 0 720 210" role="img" aria-label="Caminhões ocupados por hora no primeiro dia"><defs><linearGradient id="chart-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#4997ff" stopOpacity=".38"/><stop offset="100%" stopColor="#4997ff" stopOpacity=".015"/></linearGradient></defs>{[0,.25,.5,.75,1].map(k=><g key={k}><line x1="42" x2="695" y1={178-k*130} y2={178-k*130} stroke="#29394c" strokeDasharray="3 5"/><text x="8" y={183-k*130} fill="#91a2b9" fontSize="12">{Math.round(k*max)}</text></g>)}<path d={`${line} L695,178 L42,178 Z`} fill="url(#chart-fill)"/><path d={line} fill="none" stroke="#6daaff" strokeWidth="3" strokeLinejoin="round"/>{[0,4,8,12,16,20,24].map(h=><text key={h} x={42+h*27.2} y="205" textAnchor="middle" fill="#a5b3c8" fontSize="12">{String(h).padStart(2,'0')}h</text>)}<line x1={42+cursor/60*27.2} x2={42+cursor/60*27.2} y1="25" y2="178" stroke="#63dec7" strokeDasharray="4 4"/><circle cx={42+cursor/60*27.2} cy={178-(result.hourly[Math.min(24,Math.round(cursor/60))]?.busy??0)/max*130} r="5" fill="#63dec7" stroke="#15243a" strokeWidth="3"/></svg><Slider aria-label="Horário de inspeção da frota" min={0} max={1440} step={15} value={[cursor]} onValueChange={v=>onCursor(v[0])}/></div>}
function Network({result,routes}:{result:Result;routes:Route[]}){const groups=routes.slice(0,5).map(r=>({r,count:result.trips.filter(t=>t.routeId===r.id).length}));return <svg className="network" viewBox="0 0 600 225" role="img" aria-label="Diagrama esquemático de origem e destino das viagens, sem coordenadas geográficas"><defs><linearGradient id="flow" x1="0" x2="1"><stop stopColor="#80b5ff"/><stop offset="1" stopColor="#2771f2"/></linearGradient></defs>{groups.map(({r,count},i)=><g key={r.id}><path d={`M185 ${26+i*43} C290 ${26+i*43},230 111,327 111`} fill="none" stroke={count?'#9dc3fb':'#d9e0eb'} strokeWidth={count?2:1} strokeDasharray={count?'':'4 4'}/><rect x="8" y={10+i*43} width="178" height="32" rx="7" fill="#f4f7fc" stroke="#e3e9f3"/><circle cx="23" cy={26+i*43} r="4" fill={count?'#327bf3':'#a8b6c9'}/><text x="36" y={30+i*43} fontSize="12" fill="#47566e">{r.city.length>20?r.city.slice(0,18)+'…':r.city}</text><text x="172" y={30+i*43} textAnchor="end" fontSize="12" fill="#1d5ed2">{count}</text></g>)}<path d="M350 111 C412 111,393 57,450 57 M350 111 C412 111,393 167,450 167" stroke="url(#flow)" strokeWidth="2" fill="none"/><circle cx="336" cy="111" r="27" fill="#e9f1ff"/><circle cx="336" cy="111" r="19" fill="#196aee"/><path d="M327 117 334 104h4l-7 13m6 0 4-7 4 7" stroke="white" strokeWidth="2" fill="none"/>{(['ave','real']as Plant[]).map((p,i)=><g key={p}><rect x="450" y={34+i*110} width="143" height="50" rx="9" fill={i?'#f0faf7':'#eef4ff'} stroke={i?'#cfe8df':'#d4e1fa'}/><text x="464" y={54+i*110} fontSize="13" fontWeight="600" fill="#22344c">{plantName(p)}</text><text x="464" y={72+i*110} fontSize="12" fill="#5a718e">{result.plants[p].trips} cargas programadas</text></g>)}</svg>}
function Gantt({result,day=0,onTrip,limit=8,cursor=720}:{result:Result;day?:number;onTrip:(t:Trip)=>void;limit?:number;cursor?:number}){const names=[...new Set(result.trips.filter(t=>t.day===day).map(t=>t.truck))].slice(0,limit);const start=day*1440-360,end=day*1440+1800,span=end-start;return <div className="gantt-scroll"><div className="gantt"><div className="gantt-head"><span>CAMINHÃO</span><div>{[-6,0,6,12,18,24,30].map(h=><span key={h} style={{left:`${(h+6)/36*100}%`}}>{h<0?'18h D−1':h>=24?`${String(h-24).padStart(2,'0')}h D+1`:`${String(h).padStart(2,'0')}h`}</span>)}</div></div>{names.map(name=><div className="gantt-row" key={name}><div className="truck-label"><Truck size={15}/>{name}</div><div className="gantt-track">{[-6,0,6,12,18,24,30].map(h=><i key={h} style={{left:`${(h+6)/36*100}%`}}/>)}{result.trips.filter(t=>t.truck===name&&t.end>start&&t.start<end).map(t=><button key={t.id} className={`gantt-trip ${t.plant}`} style={{left:`${Math.max(0,(t.start-start)/span*100)}%`,width:`${(Math.min(t.end,end)-Math.max(t.start,start))/span*100}%`}} title={`${t.id} · ${t.city} · ${clock(t.start)} a ${clock(t.end)}`} onClick={()=>onTrip(t)}><span style={{width:`${(t.loadStart-t.start)/(t.end-t.start)*100}%`}}/><span className="load" style={{width:`${(t.loadedStart-t.loadStart)/(t.end-t.start)*100}%`}}/><span className="loaded" style={{width:`${(t.dock-t.loadedStart)/(t.end-t.start)*100}%`}}/><span className="plant" style={{width:`${(t.end-t.dock)/(t.end-t.start)*100}%`}}/><b>{t.id} · {t.shed}</b></button>)}<div className="gantt-cursor" style={{left:`${(day*1440+cursor-start)/span*100}%`}}/></div></div>)}{!names.length&&<Empty icon={CalendarDays} title="Sem viagens neste dia">Revise a demanda, o estoque de aves e os tempos cadastrados.</Empty>}</div></div>}
function TripTable({trips,onTrip}:{trips:Trip[];onTrip:(t:Trip)=>void}){return <Table><TableHeader><TableRow>{['Carga / caminhão','Origem','Destino','Aves','Saída','Descarga','Retorno'].map(x=><TableHead key={x}>{x}</TableHead>)}</TableRow></TableHeader><TableBody>{trips.map(t=><TableRow key={t.id} className="click-row" onClick={()=>onTrip(t)}><TableCell><button className="text-link" onClick={e=>{e.stopPropagation();onTrip(t)}}>{t.id}</button><small>{t.truck}</small></TableCell><TableCell>{t.shed}<small>{t.city}</small></TableCell><TableCell><Pill tone={t.plant==='ave'?'blue':'green'}>{plantName(t.plant)}</Pill></TableCell><TableCell className="numeric">{fmt(t.birds)}</TableCell><TableCell>{clock(t.start)}</TableCell><TableCell>{clock(t.dock)}</TableCell><TableCell>{clock(t.end)}</TableCell></TableRow>)}</TableBody></Table>}
function Field({label,children,hint}:{label:string;children:React.ReactNode;hint?:string}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>}
function NumberField({label,value,onChange,min=0,max=1000000,step=1,hint}:{label:string;value:number;onChange:(n:number)=>void;min?:number;max?:number;step?:number;hint?:string}){return <Field label={label} hint={hint}><input type="number" value={value} min={min} max={max} step={step} onChange={e=>onChange(Number(e.target.value))}/></Field>}
function TimeField({label,value,onChange}:{label:string;value:number;onChange:(v:number)=>void}){return <Field label={label}><input type="time" value={`${String(Math.floor(value/60)).padStart(2,'0')}:${String(value%60).padStart(2,'0')}`} onChange={e=>{const [h,m]=e.target.value.split(':').map(Number);if(Number.isFinite(h+m))onChange(h*60+m)}}/></Field>}
export default function App(){
 const [ws,setWs]=useState<Workspace|null>(null),[revision,setRevision]=useState(0),[loadError,setLoadError]=useState(''),[saving,setSaving]=useState(false),[view,setView]=useState<View>('overview'),[config,setConfig]=useState<Config>({...defaultConfig}),[cursor,setCursor]=useState(720),[playing,setPlaying]=useState(false),[trip,setTrip]=useState<Trip|null>(null),[routeEdit,setRouteEdit]=useState<Route|null>(null),[importOpen,setImportOpen]=useState(false),[importText,setImportText]=useState(''),[replaceDemo,setReplaceDemo]=useState(true),[search,setSearch]=useState(''),[destination,setDestination]=useState('all'),[day,setDay]=useState('0'),[deleteId,setDeleteId]=useState<string|null>(null),[scenarioOpen,setScenarioOpen]=useState(false),[scenarioName,setScenarioName]=useState(''),[qualityOpen,setQualityOpen]=useState(false),[restoreOpen,setRestoreOpen]=useState<Workspace|null>(null),[loss,setLoss]=useState<LossRecord>({id:'',date:defaultConfig.date,plant:'ave',routeId:'',truck:'TB-01',loaded:3762,dead:0,minutes:180,note:''});
 const fileRef=useRef<HTMLInputElement>(null),backupRef=useRef<HTMLInputElement>(null);const saveLock=useRef(false);
 async function load(){setLoadError('');try{const r=await fetch('/api/workspace',{cache:'no-store'});const d=await r.json() as {workspace:Workspace;revision:number;error?:string};if(!r.ok)throw new Error(d.error);validateWorkspace(d.workspace);setWs(d.workspace);setRevision(d.revision);setConfig(d.workspace.config);}catch(e){setLoadError((e as Error).message||'Não foi possível carregar a central.');}}
 useEffect(()=>{void load()},[]);
 async function persist(next:Workspace,message='Alterações salvas'){if(saveLock.current){toast.info('Aguarde o salvamento em andamento.');return false;}saveLock.current=true;setSaving(true);try{validateWorkspace(next);const r=await fetch('/api/workspace',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({workspace:next,revision})});const d=await r.json() as {workspace:Workspace;revision:number;error?:string};if(!r.ok)throw new Error(d.error);setWs(next);setRevision(d.revision);toast.success(message);return true;}catch(e){toast.error((e as Error).message);return false;}finally{saveLock.current=false;setSaving(false);}}
 const calculation=useMemo(()=>{if(!ws)return{result:null,error:''};try{return{result:simulate(config,ws.routes,ws.trucks),error:''};}catch(e){return{result:null,error:(e as Error).message}}},[ws,config]);const result=calculation.result;
 useEffect(()=>{if(!playing)return;const t=setInterval(()=>setCursor(c=>c>=1440?0:c+15),450);return()=>clearInterval(t)},[playing]);
 useEffect(()=>{const context=(document as unknown as {modelContext?:{registerTool:(tool:unknown,options:unknown)=>Promise<void>}}).modelContext;if(!context?.registerTool||!ws||!result)return;const ctrl=new AbortController();void Promise.resolve(context.registerTool({name:'read_transport_scenario',description:'Lê os parâmetros e resultados do cenário de transporte visível, sem modificar dados.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:(input:unknown)=>{if(!input||typeof input!=='object'||Object.keys(input).length)throw new Error('Informe um objeto vazio.');return{config,requested:result.requested,scheduled:result.delivered,trips:result.trips.length,peak:result.peak,demo:ws.routes.some(r=>r.source==='demo')};}},{signal:ctrl.signal})).catch(()=>{});return()=>ctrl.abort()},[ws,config,result]);
 const filteredRoutes=useMemo(()=>ws?.routes.filter(r=>(destination==='all'||r.destination===destination||r.destination==='both')&&`${r.farm} ${r.shed} ${r.city}`.toLowerCase().includes(search.toLowerCase()))??[],[ws,search,destination]);
 const imported=useMemo(()=>{if(!importText)return null;try{return parseRoutes(importText)}catch(e){return{routes:[],errors:[(e as Error).message],total:0}}},[importText]);
 if(!ws)return <div className="loading-screen"><img src="/favicon.svg" alt="Avialog"/><h1>avialog</h1>{loadError?<><p>{loadError}</p><button className="btn primary" onClick={load}><RefreshCw size={16}/>Tentar novamente</button><p className="subtle">Na versão para computador, abra o sistema pelo arquivo INICIAR.bat.</p></>:<><LoaderCircle className="spin"/><p>Preparando a central de planejamento…</p></>}</div>;
 const c=config,res=result;const coverage=res&&res.requested?res.delivered/res.requested*100:0;const demo=ws.routes.some(r=>r.source==='demo');const dirty=JSON.stringify(c)!==JSON.stringify(ws.config);const set=(key:keyof Config,v:unknown)=>setConfig(p=>({...p,[key]:v}));
 async function saveConfig(){if(await persist({...ws!,config:c},'Parâmetros salvos.')){}}
 function exportTrips(){if(!res)return;const header=['carga','caminhao','data','granja','galpao','cidade','destino','aves','saida','carregamento','descarga','retorno'];const rows=res.trips.map(t=>[t.id,t.truck,datePlus(c.date,t.day),t.farm,t.shed,t.city,plantName(t.plant),t.birds,clock(t.start),clock(t.loadStart),clock(t.dock),clock(t.end)]);download('avialog-programacao.csv','\uFEFF'+[header,...rows].map(row=>row.map(csvCell).join(';')).join('\n'),'text/csv;charset=utf-8');toast.success('Programação exportada.');}
 async function saveRoute(e:React.FormEvent){e.preventDefault();if(!routeEdit)return;try{validateRoute(routeEdit);const duplicate=ws!.routes.some(r=>r.id!==routeEdit.id&&r.farm.toLowerCase()===routeEdit.farm.toLowerCase()&&r.shed.toLowerCase()===routeEdit.shed.toLowerCase());if(duplicate)throw new Error('Este galpão já existe nesta granja.');const next=ws!.routes.some(r=>r.id===routeEdit.id)?ws!.routes.map(r=>r.id===routeEdit.id?routeEdit:r):[...ws!.routes,routeEdit];if(await persist({...ws!,routes:next},'Galpão salvo.'))setRouteEdit(null);}catch(e){toast.error((e as Error).message)}}
 async function applyImport(){if(!imported||imported.errors.length||!imported.routes.length)return;const next=replaceDemo?ws!.routes.filter(r=>r.source!=='demo'):[...ws!.routes];for(const r of imported.routes){const index=next.findIndex(x=>x.farm.toLowerCase()===r.farm.toLowerCase()&&x.shed.toLowerCase()===r.shed.toLowerCase());if(index>=0)next[index]={...r,id:next[index].id};else next.push(r);}if(await persist({...ws!,routes:next},`${imported.routes.length} galpões importados.`)){setImportOpen(false);setImportText('');}}
 async function saveScenario(e:React.FormEvent){e.preventDefault();if(!res||!scenarioName.trim())return;if(ws!.scenarios.length>=30){toast.error('Limite de 30 cenários. Exclua um cenário antes de salvar outro.');return;}const snapshot={id:uid(),name:scenarioName.trim(),createdAt:new Date().toISOString(),config:{...c},routes:structuredClone(ws!.routes),trucks:structuredClone(ws!.trucks),summary:{delivered:res.delivered,requested:res.requested,trips:res.trips.length,peak:res.peak}};if(await persist({...ws!,config:c,scenarios:[snapshot,...ws!.scenarios]},'Cenário salvo com os dados usados na análise.')){setScenarioOpen(false);setScenarioName('');}}
 async function saveLoss(e:React.FormEvent){e.preventDefault();if(!loss.routeId){toast.error('Selecione o galpão de origem.');return;}if(await persist({...ws!,records:[{...loss,id:uid()},...ws!.records]},'Transporte registrado.'))setQualityOpen(false);}
 const title=nav.find(n=>n.id===view)!.label;
 const makeRoute=()=>setRouteEdit({id:uid(),farm:'',shed:'',city:'',birds:0,emptyMin:90,aveMin:null,realMin:null,destination:'both',blockedUntil:'',source:'manual'});
 return <SidebarProvider style={{'--sidebar-width':'254px'}as React.CSSProperties}><Toaster position="top-right" richColors theme="light"/><Nav view={view} setView={v=>{setView(v);setSearch('')}}/><main className="main"><header className="topbar"><div className="breadcrumb"><SidebarTrigger className="mobile-toggle"/><span>Operação avícola</span><ChevronRight size={14}/><strong>{title}</strong></div><div className="top-actions"><span className="save-status">{saving?<LoaderCircle size={14} className="spin"/>:<CheckCircle2 size={14}/>}<span>{saving?'Salvando…':'Dados carregados'}</span></span><button className="icon-button" aria-label="Regras e hipóteses" onClick={()=>setView('settings')}><HelpCircle size={19}/></button><span className="mini-avatar">DA</span></div></header><div className="page"><div className="page-heading"><div><div className="eyebrow">TRANS BRASÍLIA <span>/</span> PLANEJAMENTO INTELIGENTE</div><h1>{view==='overview'?'Visão da operação':title}</h1><p>{view==='overview'?'Toda a jornada da carga. Uma visão para decidir.':view==='simulation'?'Teste uma decisão antes de colocá-la na estrada.':view==='planning'?'Cada carga, cada caminhão, cada etapa da jornada.':view==='routes'?'Uma base confiável começa em cada galpão.':view==='fleet'?'Disponibilidade dos veículos que movem a operação.':view==='quality'?'Perdas de transporte acompanhadas separadamente da criação.':'Parâmetros explícitos para decisões rastreáveis.'}</p></div><div className="heading-actions"><button className="btn secondary" onClick={()=>setImportOpen(true)}><FileUp size={16}/>Importar rotas</button><button className="btn primary" onClick={()=>{setView('simulation');setScenarioOpen(true)}}><Plus size={17}/>Salvar cenário</button></div></div>
 <div className={`context-bar ${demo?'demo':''}`}><div><FlaskConical size={16}/><strong>{demo?'Ambiente de demonstração':'Simulação operacional'}</strong><span>{demo?'Rotas e volumes ilustrativos · parâmetros editáveis':'Resultado calculado com a base cadastrada'}</span></div><button onClick={()=>setView('settings')}>Ver premissas <ChevronRight size={14}/></button></div>
 <div className="filterbar"><div className="date-filter"><CalendarDays size={16}/><input aria-label="Data inicial da simulação" type="date" value={c.date} onChange={e=>set('date',e.target.value)}/></div><Pick label="Horizonte da simulação" value={String(c.days)} onChange={v=>{set('days',Number(v));setDay('0')}} items={[{value:'1',label:'Visão diária'},{value:'7',label:'Próximos 7 dias'},{value:'15',label:'Próximos 15 dias'},{value:'45',label:'Horizonte de 45 dias'}]}/><span className="filter-note"><span className="legend-dot blue"/>{c.boxes} caixas · {c.density} aves/caixa</span><div className="filter-end">{dirty&&<span className="draft-label">Parâmetros não salvos</span>}<button className="btn small secondary" disabled={saving||!!calculation.error} onClick={saveConfig}><Save size={15}/>Salvar parâmetros</button><button className="icon-button" title="Exportar programação CSV" aria-label="Exportar programação" onClick={exportTrips}><Download size={18}/></button></div></div>
 {calculation.error?<div className="error-box"><TriangleAlert/>{calculation.error}<button className="btn secondary" onClick={()=>setConfig(ws.config)}>Restaurar parâmetros salvos</button></div>:res&&<>
 {(view==='overview'||view==='simulation'||view==='planning')&&<div className="stats-grid"><Stat icon={Truck} label="Frota disponível no cenário" value={res.active} unit={`/ ${ws.trucks.length}`} note={<><span className="legend-dot amber"/>{ws.trucks.length-res.active} fora da programação</>} tone="amber"/><Stat icon={Boxes} label="Aves programadas" value={fmt(res.delivered)} note={`${pct(coverage)} da demanda de ${fmt(res.requested)}`} tone={coverage>=99.9?'green':'blue'}/><Stat icon={RouteIcon} label="Viagens programadas" value={res.trips.length} unit="cargas" note={`${fmt(c.boxes*c.density)} aves por carga completa`}/><Stat icon={Clock3} label="Ciclo médio calculado" value={res.avgCycle?`${Math.floor(res.avgCycle/60)}h${String(Math.round(res.avgCycle%60)).padStart(2,'0')}`:'—'} note="Da saída até o retorno à Trans Brasília" tone="muted"/></div>}
 {view==='overview'&&<><div className="overview-grid"><section className="panel dark-panel"><div className="panel-header"><div><div className="overline">PULSO DA OPERAÇÃO</div><h2>Ocupação da frota</h2></div><Pill tone="dark">Primeiro dia · simulado</Pill></div><div className="pulse-summary"><div><strong>{res.trips.filter(t=>t.start<=cursor&&t.end>cursor).length}</strong><span>caminhões em ciclo<br/>às {clock(cursor)}</span></div><div className="pulse-detail"><span>Pico de ocupação</span><b>{res.peak} caminhões</b></div><button className="play-button" aria-label={playing?'Pausar simulação visual':'Reproduzir simulação visual'} onClick={()=>setPlaying(!playing)}>{playing?<Pause size={17}/>:<Play size={17}/>}</button></div><OccupancyChart result={res} cursor={cursor} onCursor={setCursor}/><div className="chart-foot"><span><i/>Frota em operação</span><span>Inspecione o dia pela linha do tempo</span></div></section><section className="panel insights-panel"><div className="panel-header"><h2><Sparkles size={18}/>Leitura do cenário</h2><Pill tone="neutral">Calculada</Pill></div><div className="insight-lead"><span className={`insight-icon ${coverage>=99.9?'success':''}`}>{coverage>=99.9?<CheckCircle2/>:<TriangleAlert/>}</span><div><h3>{coverage>=99.9?'Demanda atendida no cenário':'Há demanda sem programação'}</h3><p>{coverage>=99.9?'A agenda calculada atende o volume informado dentro das janelas configuradas.':`${fmt(res.requested-res.delivered)} aves ainda não têm uma viagem viável nesta agenda.`}</p></div></div><div className="insight-row"><Truck size={18}/><div><b>{res.peak} veículos simultâneos</b><p>Maior ocupação encontrada na programação.</p></div></div><div className="insight-row"><Warehouse size={18}/><div><b>{fmt(res.left)} aves na base após a simulação</b><p>Estoque restante, sem reposição automática.</p></div></div><button className="btn secondary full" onClick={()=>setView('simulation')}><GitCompareArrows size={16}/>Comparar alternativas</button><small className="insight-foot">Agenda heurística. Não comprova frota mínima.</small></section></div>
 <div className="two-columns"><section className="panel"><div className="panel-header"><div><h2>Atendimento por frigorífico</h2><p>Volume programado dentro da janela</p></div><Factory size={20}/></div>{(['ave','real']as Plant[]).map(p=>{const v=res.plants[p],pc=v.requested?v.delivered/v.requested*100:0;return <div className="plant-row" key={p}><div className={`plant-symbol ${p}`}><Factory size={20}/></div><div className="plant-data"><div><strong>{plantName(p)}</strong><span>{pct(pc)}</span></div><div className="meter"><span className={p} style={{width:`${Math.min(100,pc)}%`}}/></div><div className="plant-meta"><span>{fmt(v.delivered)} / {fmt(v.requested)} aves</span><span>{v.trips} cargas</span></div></div></div>})}<div className="panel-bottom"><Clock3 size={14}/><span>Real: até {clock(c.realClose)} · horário ajustável nas regras</span></div></section><section className="panel"><div className="panel-header"><div><h2>Conexões da operação</h2><p>Origens e destinos das cargas programadas</p></div><RouteIcon size={20}/></div><Network result={res} routes={ws.routes}/><div className="panel-bottom">Diagrama de fluxo · 5 primeiras origens · sem geolocalização</div></section></div>
 <section className="panel"><div className="panel-header"><div><h2>Jornada dos caminhões</h2><p>Saída, carregamento, transporte e retorno · primeiro dia</p></div><button className="text-link" onClick={()=>setView('planning')}>Ver programação completa <ChevronRight size={15}/></button></div><Gantt result={res} onTrip={setTrip} cursor={cursor}/><div className="gantt-legend"><span><i className="leg-empty"/>Ida vazia</span><span><i className="leg-load"/>Carregamento</span><span><i className="leg-loaded"/>Viagem carregada</span><span><i className="leg-plant"/>Frigorífico e retorno</span><span>Clique em uma carga para inspecionar</span></div></section></>}
 {view==='simulation'&&<><div className="simulation-layout"><section className="panel control-panel"><div className="panel-header"><div><h2><SlidersHorizontal size={18}/>Ajuste o cenário</h2><p>Resultados recalculados a cada alteração</p></div></div><div className="controls"><div className="range-field"><label>Indisponíveis adicionais <b>{c.unavailable} veículos</b></label><Slider aria-label="Caminhões indisponíveis adicionais" value={[c.unavailable]} min={0} max={ws.trucks.filter(t=>t.status==='available').length} step={1} onValueChange={v=>set('unavailable',v[0])}/><small>Além dos veículos marcados em manutenção.</small></div><div className="range-field"><label>Atraso por viagem carregada <b>{c.delayMin} min</b></label><Slider aria-label="Atraso por viagem" value={[c.delayMin]} min={0} max={120} step={5} onValueChange={v=>set('delayMin',v[0])}/></div><div className="field"><span>Aves por caixa · cenário</span><Pick label="Aves por caixa" value={String(c.density)} onChange={v=>set('density',Number(v))} items={[{value:'6',label:'6 aves · referência'},{value:'7',label:'7 aves · hipótese a validar'},{value:'8',label:'8 aves · hipótese a validar'}]}/><small>7 ou 8 aves exigem validação operacional; não são recomendações.</small></div><div className="field"><span>Retorno à Trans Brasília</span><Pick label="Tempo de retorno" value={String(c.returnMin)} onChange={v=>set('returnMin',Number(v))} items={[70,75,80].map(v=>({value:String(v),label:`${v} minutos`}))}/></div><div className="switch-row"><div><strong>Carregamento noturno</strong><small>{clock(c.nightStart)}–{clock(c.nightEnd)} · janela configurável</small></div><Switch aria-label="Limitar carregamento ao período noturno" checked={c.nightOnly} onCheckedChange={v=>set('nightOnly',v)}/></div><button className="btn primary full" onClick={()=>setScenarioOpen(true)}><Save size={16}/>Salvar este cenário</button><button className="text-link centered" onClick={()=>setConfig(ws.config)}>Restaurar parâmetros salvos</button></div></section><div className="simulation-results"><section className="panel"><div className="panel-header"><div><h2>O que muda na operação?</h2><p>Mesmo estoque e mesmas janelas para comparar</p></div><GitCompareArrows size={20}/></div><div className="comparison-cards">{[{label:'Seu cenário',unavailable:c.unavailable,delay:c.delayMin},{label:'Sem indisponíveis adicionais',unavailable:0,delay:c.delayMin},{label:'Mais 30 min de viagem',unavailable:c.unavailable,delay:c.delayMin+30}].map((s,i)=>{const r=i===0?res:simulate({...c,unavailable:s.unavailable,delayMin:s.delay},ws.routes,ws.trucks);return <div className={`comparison-card ${i===0?'selected':''}`} key={s.label}><span>{s.label}</span><strong>{pct(r.requested?r.delivered/r.requested*100:0)}</strong><small>da demanda programada</small><div><span>Cargas</span><b>{r.trips.length}</b></div><div><span>Pico da frota</span><b>{r.peak}</b></div><div><span>Aves sem agenda</span><b>{fmt(r.requested-r.delivered)}</b></div>{i>0&&<button className="btn small secondary full" onClick={()=>setConfig({...c,unavailable:s.unavailable,delayMin:s.delay})}>Aplicar cenário</button>}</div>})}</div></section><section className="panel"><div className="panel-header"><div><h2>Capacidade ao longo do horizonte</h2><p>O estoque cadastrado é consumido uma única vez.</p></div><Pill tone="neutral">{c.days} {c.days===1?'dia':'dias'}</Pill></div><div className="daily-bars">{res.days.map(d=><div key={d.day} title={`${shortDate(d.date)}: ${fmt(d.delivered)} de ${fmt(d.requested)} aves`}><div className="daily-bar-track"><span style={{height:`${d.requested?d.delivered/d.requested*100:0}%`}}/></div><small>{d.date.slice(8)}</small></div>)}</div><div className="panel-bottom"><span className="legend-dot blue"/>Volume atendido / demanda diária · dias sem abate permanecem vazios</div></section></div></div><section className="panel"><div className="panel-header"><div><h2>Cenários salvos</h2><p>Parâmetros e base de rotas preservados em cada análise</p></div><Pill tone="neutral">{ws.scenarios.length}/30</Pill></div>{!ws.scenarios.length?<Empty icon={FlaskConical} title="Sua primeira análise começa aqui">Salve um cenário para comparar resultados e retomar o estudo depois.</Empty>:<Table><TableHeader><TableRow>{['Cenário','Data da análise','Atendimento','Cargas','Pico','Ações'].map(t=><TableHead key={t}>{t}</TableHead>)}</TableRow></TableHeader><TableBody>{ws.scenarios.map(s=><TableRow key={s.id}><TableCell><b>{s.name}</b><small>{s.routes.length} galpões · {s.config.days} dia(s)</small></TableCell><TableCell>{new Date(s.createdAt).toLocaleDateString('pt-BR')}</TableCell><TableCell>{pct(s.summary.requested?s.summary.delivered/s.summary.requested*100:0)}</TableCell><TableCell>{s.summary.trips}</TableCell><TableCell>{s.summary.peak}</TableCell><TableCell><button className="text-link" onClick={()=>setRestoreOpen({...ws,config:s.config,routes:s.routes,trucks:s.trucks})}>Restaurar base</button><button className="icon-button danger" aria-label={`Excluir cenário ${s.name}`} onClick={()=>setDeleteId('scenario:'+s.id)}><Trash2 size={15}/></button></TableCell></TableRow>)}</TableBody></Table>}</section></>}
 {view==='planning'&&<section className="panel"><div className="panel-header"><div><h2>Programação detalhada</h2><p>Agenda calculada · clique na carga para abrir todas as etapas</p></div><div className="inline-actions"><Pick label="Dia da programação" value={day} onChange={setDay} items={res.days.map(d=>({value:String(d.day),label:shortDate(d.date)}))}/><button className="btn secondary" onClick={exportTrips}><Download size={16}/>Exportar CSV</button></div></div><Tabs defaultValue="timeline" className="planning-tabs"><TabsList><TabsTrigger value="timeline">Linha do tempo</TabsTrigger><TabsTrigger value="table">Lista de cargas</TabsTrigger></TabsList><TabsContent value="timeline"><Gantt result={res} day={Math.min(Number(day),c.days-1)} onTrip={setTrip} limit={100}/></TabsContent><TabsContent value="table"><TripTable trips={res.trips.filter(t=>t.day===Math.min(Number(day),c.days-1))} onTrip={setTrip}/></TabsContent></Tabs><div className="panel-bottom">D−1 indica partida no dia anterior. D+1 indica retorno no dia seguinte. Uma viagem só libera o caminhão após o retorno.</div></section>}
 </>}
 {view==='routes'&&<><div className="mini-stats"><div><Warehouse/><span>Galpões cadastrados<strong>{ws.routes.length}</strong></span></div><div><MapPin/><span>Cidades<strong>{new Set(ws.routes.map(r=>r.city)).size}</strong></span></div><div><Boxes/><span>Aves na base<strong>{fmt(ws.routes.reduce((s,r)=>s+r.birds,0))}</strong></span></div><div><TriangleAlert/><span>Sem tempo para ambos<strong>{ws.routes.filter(r=>r.aveMin===null&&r.realMin===null).length}</strong></span></div></div><section className="panel"><div className="panel-header"><div className="searchbox"><Search size={17}/><input aria-label="Buscar granja, galpão ou cidade" placeholder="Buscar granja, galpão ou cidade…" value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="inline-actions"><Pick label="Filtrar destino" value={destination} onChange={setDestination} items={[{value:'all',label:'Todos os destinos'},{value:'ave',label:'Ave Nova'},{value:'real',label:'Real Alimentos'}]}/><button className="btn primary" onClick={makeRoute}><Plus size={16}/>Novo galpão</button></div></div><Table><TableHeader><TableRow>{['Granja / galpão','Cidade','Aves','Ida vazia','Até Ave Nova','Até Real','Origem',''].map((h,i)=><TableHead key={i}>{h}</TableHead>)}</TableRow></TableHeader><TableBody>{filteredRoutes.map(r=><TableRow key={r.id}><TableCell><button className="text-link" onClick={()=>setRouteEdit({...r})}>{r.shed}</button><small>{r.farm}</small>{r.blockedUntil&&<small className="amber">Bloqueado até {r.blockedUntil}</small>}</TableCell><TableCell>{r.city}</TableCell><TableCell className="numeric">{fmt(r.birds)}</TableCell><TableCell>{r.emptyMin} min</TableCell><TableCell>{r.aveMin===null?<Pill tone="amber">Pendente</Pill>:`${r.aveMin} min`}</TableCell><TableCell>{r.realMin===null?<Pill tone="amber">Pendente</Pill>:`${r.realMin} min`}</TableCell><TableCell><Pill tone={r.source==='demo'?'amber':'neutral'}>{r.source==='demo'?'Demonstração':r.source==='import'?'Importado':'Cadastro'}</Pill></TableCell><TableCell><button className="icon-button" aria-label={`Editar galpão ${r.shed}`} onClick={()=>setRouteEdit({...r})}><Settings2 size={16}/></button><button className="icon-button danger" aria-label={`Excluir galpão ${r.shed}`} onClick={()=>setDeleteId('route:'+r.id)}><Trash2 size={16}/></button></TableCell></TableRow>)}</TableBody></Table>{!filteredRoutes.length&&<Empty title="Nenhum galpão encontrado">Ajuste a busca ou cadastre uma nova origem.</Empty>}<div className="panel-bottom">{filteredRoutes.length} galpões exibidos · tempos separados por frigorífico · identificadores preservados</div></section></>}
 {view==='fleet'&&<><div className="callout"><Wrench size={20}/><div><strong>Disponibilidade real e hipótese de manutenção</strong><p>Os veículos marcados abaixo saem da programação. No simulador, você ainda pode retirar veículos adicionais para testar imprevistos.</p></div></div><div className="fleet-grid">{ws.trucks.map(t=>{const tt=res?.trips.filter(x=>x.truck===t.id)??[];return <article className={`panel truck-card ${t.status==='maintenance'?'maintenance':''}`} key={t.id}><div className="truck-card-top"><span className="truck-symbol"><Truck size={28}/></span><Pill tone={t.status==='available'?'green':'amber'}>{t.status==='available'?'Disponível':'Manutenção'}</Pill></div><h2>{t.name}</h2><p>{tt.length} cargas na simulação · {fmt(tt.reduce((s,x)=>s+x.birds,0))} aves</p><div className="truck-util"><span style={{width:`${Math.min(100,tt.reduce((s,x)=>s+x.end-x.start,0)/(c.days*1440)*100)}%`}}/></div><div className="switch-row"><span>Em manutenção</span><Switch disabled={saving} aria-label={`${t.name} em manutenção`} checked={t.status==='maintenance'} onCheckedChange={v=>void persist({...ws,trucks:ws.trucks.map(x=>x.id===t.id?{...x,status:v?'maintenance':'available'}:x)},'Disponibilidade atualizada.')}/></div></article>})}</div></>}
 {view==='quality'&&<><div className="stats-grid"><Stat icon={ShieldCheck} label="Mortalidade de transporte" value={ws.records.length?pct(ws.records.reduce((s,r)=>s+r.dead,0)/ws.records.reduce((s,r)=>s+r.loaded,0)*100):'—'} note="Mortas / carregadas · registros reais"/><Stat icon={Boxes} label="Aves carregadas registradas" value={fmt(ws.records.reduce((s,r)=>s+r.loaded,0))} note="Somente transportes cadastrados"/><Stat icon={Activity} label="Perdas registradas" value={fmt(ws.records.reduce((s,r)=>s+r.dead,0))} unit="aves" note="Sem mistura com mortalidade de criação" tone="amber"/><Stat icon={Truck} label="Transportes registrados" value={ws.records.length} note="Dados de execução, separados da simulação"/></div><section className="panel"><div className="panel-header"><div><h2>Monitoramento de perdas</h2><p>Registre a carga executada para acompanhar os resultados.</p></div><button className="btn primary" onClick={()=>{setLoss({...loss,date:c.date});setQualityOpen(true)}}><Plus size={16}/>Registrar transporte</button></div>{!ws.records.length?<Empty icon={ShieldCheck} title="Qualidade começa com um registro confiável">Ainda não há transportes executados cadastrados. Nenhum percentual de mortalidade foi inventado para preencher o painel.</Empty>:<Table><TableHeader><TableRow>{['Data / caminhão','Origem','Destino','Carregadas','Mortas','Taxa','Viagem',''].map((h,i)=><TableHead key={i}>{h}</TableHead>)}</TableRow></TableHeader><TableBody>{ws.records.map(r=><TableRow key={r.id}><TableCell>{shortDate(r.date)}<small>{r.truck}</small></TableCell><TableCell>{ws.routes.find(x=>x.id===r.routeId)?.shed??'Origem removida'}<small>{r.note}</small></TableCell><TableCell>{plantName(r.plant)}</TableCell><TableCell>{fmt(r.loaded)}</TableCell><TableCell>{fmt(r.dead)}</TableCell><TableCell><Pill tone={r.dead?'amber':'green'}>{pct(r.dead/r.loaded*100)}</Pill></TableCell><TableCell>{r.minutes} min</TableCell><TableCell><button className="icon-button danger" aria-label="Excluir registro" onClick={()=>setDeleteId('record:'+r.id)}><Trash2 size={16}/></button></TableCell></TableRow>)}</TableBody></Table>}</section><div className="callout"><ShieldCheck/><div><strong>Uma métrica independente</strong><p>A faixa de 6% a 15% discutida para o planejamento da criação não é uma meta de mortalidade de transporte. Aqui, cada perda é apurada sobre as aves efetivamente carregadas.</p></div></div></>}
 {view==='settings'&&<><div className="settings-grid"><section className="panel"><div className="panel-header"><h2><Factory size={19}/>Demanda e janelas</h2></div><div className="form-grid"><NumberField label="Ave Nova · aves por dia útil" value={c.aveTarget} onChange={v=>set('aveTarget',v)}/><NumberField label="Real · aves por dia útil" value={c.realTarget} onChange={v=>set('realTarget',v)}/><TimeField label="Ave Nova · abre" value={c.aveOpen} onChange={v=>set('aveOpen',v)}/><TimeField label="Ave Nova · encerra" value={c.aveClose} onChange={v=>set('aveClose',v)}/><TimeField label="Real · abre" value={c.realOpen} onChange={v=>set('realOpen',v)}/><TimeField label="Real · encerra (a confirmar)" value={c.realClose} onChange={v=>set('realClose',v)}/><NumberField label="Sábado · aves por unidade" value={c.saturdayTarget} onChange={v=>set('saturdayTarget',v)}/><TimeField label="Sábado · encerra" value={c.saturdayClose} onChange={v=>set('saturdayClose',v)}/></div><div className="panel-bottom">Domingo sem demanda de abate. Janelas usadas para descarga; validar recebimento real.</div></section><section className="panel"><div className="panel-header"><h2><Clock3 size={19}/>Tempos e capacidade</h2></div><div className="form-grid"><NumberField label="Caixas por caminhão" value={c.boxes} onChange={v=>set('boxes',v)} min={1} max={1000}/><NumberField label="Carregamento · min" value={c.loadMin} onChange={v=>set('loadMin',v)} min={1} max={600}/><NumberField label="Frigorífico · permanência base" value={c.residenceMin} onChange={v=>set('residenceMin',v)} min={1} max={600}/><NumberField label="Descarga · min" value={c.unloadMin} onChange={v=>set('unloadMin',v)} min={1} max={300}/><NumberField label="Retorno · min" value={c.returnMin} onChange={v=>set('returnMin',v)} min={1} max={600}/><Field label="Base de aves cadastrada"><Pick label="Tipo de quantidade de aves" value={c.stockMode} onChange={v=>set('stockMode',v)} items={[{value:'available',label:'Disponíveis para carregar'},{value:'housed',label:'Alojadas (descontar criação)'}]}/></Field><NumberField label="Perda de criação · %" value={c.creationLoss} onChange={v=>set('creationLoss',v)} min={0} max={100} step={.1} hint="Aplicada uma vez, somente sobre aves alojadas."/><TimeField label="Janela noturna · início" value={c.nightStart} onChange={v=>set('nightStart',v)}/><TimeField label="Janela noturna · fim" value={c.nightEnd} onChange={v=>set('nightEnd',v)}/></div></section></div><section className="panel"><div className="panel-header"><div><h2>Premissas que acompanham cada resultado</h2><p>O modelo informa seus limites junto com os números.</p></div><Pill tone="amber">Em validação</Pill></div><div className="assumptions">{[['Frota compartilhada','Os 22 veículos atendem os dois frigoríficos nesta primeira hipótese. Ajuste a base antes de decidir a frota.'],['Agenda viável, não ótima','O motor aloca cargas por horários e disponibilidade. Uma demanda não atendida não comprova que todas as alternativas sejam inviáveis.'],['Permanência no frigorífico','São reservados 90 min a partir da entrada na descarga; eventuais filas adicionais são somadas. A decomposição da permanência precisa ser medida.'],['Estoque sem reposição','Cada ave cadastrada só pode ser programada uma vez no horizonte. Novos lotes não são criados automaticamente.'],['Uma origem por viagem','Sobras recebem cargas parciais quando há janela. Não há combinação automática de galpões na mesma viagem.'],['Equipes disponíveis','A primeira versão não limita motoristas ou equipes de apanha. O cenário noturno usa a janela configurada.'],['Recebimento e demanda','As capacidades informadas são usadas como metas de cenário. A janela da Real e o recebimento antecipado ainda precisam ser confirmados.'],['Condições de transporte','Densidade e atraso são parâmetros de cenário. O sistema não presume segurança de 7 ou 8 aves por caixa nem estima mortalidade a partir do clima.']].map(([title,text],i)=><div key={title}><span>{String(i+1).padStart(2,'0')}</span><div><strong>{title}</strong><p>{text}</p></div></div>)}</div></section><section className="panel"><div className="panel-header"><div><h2>Dados e continuidade</h2><p>Uma cópia inclui rotas, parâmetros, frota, cenários e registros.</p></div></div><div className="backup-actions"><button className="btn secondary" onClick={()=>download('avialog-backup.json',JSON.stringify({...ws,config:c},null,2),'application/json')}><Download size={16}/>Exportar cópia completa</button><button className="btn secondary" onClick={()=>backupRef.current?.click()}><FileUp size={16}/>Restaurar cópia</button><button className="btn primary" disabled={saving||!!calculation.error} onClick={saveConfig}><Save size={16}/>Salvar regras</button></div></section></>}
 <footer className="page-footer"><span>AVIALOG <b>·</b> Inteligência de Transporte</span><span>Resultados de simulação · versão 1.0</span></footer></div></main>
 <input ref={fileRef} className="hidden" type="file" accept=".csv,text/csv" onChange={async e=>{const f=e.target.files?.[0];if(f){if(f.size>4000000){toast.error('O CSV deve ter até 4 MB.');return;}setImportText(await f.text());}e.target.value=''}}/>
 <input ref={backupRef} className="hidden" type="file" accept=".json" onChange={async e=>{try{const f=e.target.files?.[0];if(!f)return;if(f.size>4000000)throw new Error('Arquivo acima de 4 MB.');const data=JSON.parse(await f.text());validateWorkspace(data);setRestoreOpen(data);}catch(e){toast.error((e as Error).message)}e.target.value=''}}/>
 <Dialog open={importOpen} onOpenChange={setImportOpen}><DialogContent className="wide-dialog"><DialogHeader><DialogTitle>Importar rotas e galpões</DialogTitle><DialogDescription>Envie um CSV no modelo. A prévia valida os dados antes de salvar.</DialogDescription></DialogHeader><div className="import-drop"><FileUp size={32}/><h3>Traga sua base para a central</h3><p>CSV · até 2.000 galpões · tempos em minutos</p><button className="btn primary" onClick={()=>fileRef.current?.click()}>Selecionar arquivo CSV</button><button className="text-link" onClick={()=>download('modelo-rotas-avialog.csv','\uFEFFgranja;galpao;cidade;aves;vazio_min;ave_nova_min;real_min;destino;bloqueado_ate\nGranja exemplo;G01;Pará de Minas;30000;90;180;200;both;\n','text/csv;charset=utf-8')}>Baixar modelo de importação</button></div>{imported&&<div className="import-preview"><div><Pill tone={imported.errors.length?'amber':'green'}>{imported.errors.length?'Revisão necessária':'Validação concluída'}</Pill><b>{imported.routes.length} válidos / {imported.total} linhas</b></div>{imported.errors.length?<ul>{imported.errors.slice(0,10).map((e,i)=><li key={i}>{e}</li>)}</ul>:<><p>Granja + galpão identificam o registro. Correspondências serão atualizadas; os demais serão adicionados.</p><div className="switch-row"><label htmlFor="replace-demo">Remover rotas de demonstração</label><Switch id="replace-demo" checked={replaceDemo} onCheckedChange={setReplaceDemo}/></div><div className="import-sample">{imported.routes.slice(0,3).map(r=><div key={r.id}><b>{r.shed}</b><span>{r.city}</span><span>{fmt(r.birds)} aves</span></div>)}</div></>}</div>}<button className="btn primary full" disabled={!imported?.routes.length||!!imported?.errors.length||saving} onClick={applyImport}><Check size={16}/>Confirmar importação</button></DialogContent></Dialog>
 <Dialog open={!!routeEdit} onOpenChange={v=>!v&&setRouteEdit(null)}><DialogContent className="wide-dialog"><DialogHeader><DialogTitle>Cadastro do galpão</DialogTitle><DialogDescription>Informe tempos específicos para cada destino. Campos vazios não serão estimados.</DialogDescription></DialogHeader>{routeEdit&&<form onSubmit={saveRoute}><div className="form-grid no-pad"><Field label="Granja"><input required value={routeEdit.farm} onChange={e=>setRouteEdit({...routeEdit,farm:e.target.value})}/></Field><Field label="Identificador do galpão"><input required value={routeEdit.shed} onChange={e=>setRouteEdit({...routeEdit,shed:e.target.value})}/></Field><Field label="Cidade"><input required value={routeEdit.city} onChange={e=>setRouteEdit({...routeEdit,city:e.target.value})}/></Field><NumberField label="Quantidade de aves" value={routeEdit.birds} onChange={v=>setRouteEdit({...routeEdit,birds:v})}/><NumberField label="Trans → galpão · min" value={routeEdit.emptyMin} onChange={v=>setRouteEdit({...routeEdit,emptyMin:v})} max={1440}/>{(['aveMin','realMin']as const).map(k=><Field key={k} label={`Galpão → ${k==='aveMin'?'Ave Nova':'Real'} · min`}><input type="number" min="0" max="1440" placeholder="Não informado" value={routeEdit[k]??''} onChange={e=>setRouteEdit({...routeEdit,[k]:e.target.value===''?null:Number(e.target.value)})}/></Field>)}<Field label="Destinos permitidos"><Pick label="Destino permitido" value={routeEdit.destination} onChange={v=>setRouteEdit({...routeEdit,destination:v as Route['destination']})} items={[{value:'both',label:'Ambos os frigoríficos'},{value:'ave',label:'Somente Ave Nova'},{value:'real',label:'Somente Real'}]}/></Field><Field label="Bloqueado até (inclusive)"><input type="date" value={routeEdit.blockedUntil} onChange={e=>setRouteEdit({...routeEdit,blockedUntil:e.target.value})}/></Field></div><button className="btn primary full" disabled={saving} type="submit"><Save size={16}/>Salvar galpão</button></form>}</DialogContent></Dialog>
 <Sheet open={!!trip} onOpenChange={v=>!v&&setTrip(null)}><SheetContent className="trip-sheet"><SheetHeader><SheetTitle>Carga {trip?.id}</SheetTitle><SheetDescription>Rastreabilidade da programação simulada</SheetDescription></SheetHeader>{trip&&<div className="trip-detail"><Pill tone={trip.plant==='ave'?'blue':'green'}>{plantName(trip.plant)}</Pill><h2>{trip.truck}</h2><p>{trip.farm} · {trip.shed}</p><div className="detail-stats"><div><small>Aves programadas</small><strong>{fmt(trip.birds)}</strong></div><div><small>Ciclo completo</small><strong>{minutes(trip.end-trip.start)}</strong></div></div><div className="journey">{[{title:'Saída da Trans Brasília',time:trip.start,note:`Viagem vazia · ${trip.emptyMin} min`,icon:Truck},{title:'Carregamento no galpão',time:trip.loadStart,note:`${trip.city} · ${c.loadMin} min`,icon:Warehouse},{title:'Viagem carregada',time:trip.loadedStart,note:`Até ${plantName(trip.plant)} · ${trip.loadedMin} min`,icon:RouteIcon},{title:'Chegada ao frigorífico',time:trip.arrival,note:`Espera adicional · ${Math.round(trip.wait)} min`,icon:MapPin},{title:'Entrada na descarga',time:trip.dock,note:`Descarga ${c.unloadMin} min dentro de ${c.residenceMin} min de permanência base`,icon:Factory},{title:'Retorno concluído',time:trip.end,note:'Caminhão liberado para outra viagem',icon:CheckCircle2}].map(({title,time,note,icon:Icon})=><div className="journey-step" key={title}><span><Icon size={17}/></span><div><small>{clock(time)}</small><strong>{title}</strong><p>{note}</p></div></div>)}</div></div>}</SheetContent></Sheet>
 <Dialog open={scenarioOpen} onOpenChange={setScenarioOpen}><DialogContent><DialogHeader><DialogTitle>Salvar cenário de análise</DialogTitle><DialogDescription>A base de rotas e os parâmetros serão preservados para comparação.</DialogDescription></DialogHeader><form onSubmit={saveScenario}><Field label="Nome do cenário"><input required maxLength={80} placeholder="Ex.: 20 caminhões · operação de referência" value={scenarioName} onChange={e=>setScenarioName(e.target.value)}/></Field><button className="btn primary full" disabled={saving||!res} type="submit"><Save size={16}/>Salvar cenário</button></form></DialogContent></Dialog>
 <Dialog open={qualityOpen} onOpenChange={setQualityOpen}><DialogContent className="wide-dialog"><DialogHeader><DialogTitle>Registrar transporte executado</DialogTitle><DialogDescription>Informe as contagens reais da carga e da chegada.</DialogDescription></DialogHeader><form onSubmit={saveLoss}><div className="form-grid no-pad"><Field label="Data"><input required type="date" value={loss.date} onChange={e=>setLoss({...loss,date:e.target.value})}/></Field><Field label="Destino"><Pick label="Frigorífico do registro" value={loss.plant} onChange={v=>setLoss({...loss,plant:v as Plant})} items={[{value:'ave',label:'Ave Nova'},{value:'real',label:'Real Alimentos'}]}/></Field><Field label="Galpão"><Pick label="Galpão do transporte" value={loss.routeId} onChange={v=>setLoss({...loss,routeId:v})} items={ws.routes.map(r=>({value:r.id,label:r.shed+' · '+r.farm}))}/></Field><Field label="Caminhão"><Pick label="Caminhão do transporte" value={loss.truck} onChange={v=>setLoss({...loss,truck:v})} items={ws.trucks.map(t=>({value:t.id,label:t.name}))}/></Field><NumberField label="Aves carregadas" value={loss.loaded} onChange={v=>setLoss({...loss,loaded:v})} min={1}/><NumberField label="Mortas no transporte" value={loss.dead} onChange={v=>setLoss({...loss,dead:v})} max={loss.loaded}/><NumberField label="Tempo carregado · min" value={loss.minutes} onChange={v=>setLoss({...loss,minutes:v})}/><Field label="Observações"><input maxLength={300} value={loss.note} onChange={e=>setLoss({...loss,note:e.target.value})}/></Field></div><button className="btn primary full" disabled={saving} type="submit">Salvar registro</button></form></DialogContent></Dialog>
 <AlertDialog open={!!deleteId} onOpenChange={v=>!v&&setDeleteId(null)}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Excluir este registro?</AlertDialogTitle><AlertDialogDescription>A exclusão será salva na base. Cenários anteriormente salvos mantêm sua própria cópia das rotas.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Cancelar</AlertDialogCancel><AlertDialogAction className="danger-action" onClick={async()=>{if(!deleteId)return;const [kind,...parts]=deleteId.split(':');const id=parts.join(':');const next={...ws};if(kind==='route')next.routes=ws.routes.filter(r=>r.id!==id);if(kind==='scenario')next.scenarios=ws.scenarios.filter(s=>s.id!==id);if(kind==='record')next.records=ws.records.filter(r=>r.id!==id);await persist(next,'Registro excluído.');setDeleteId(null)}}>Excluir registro</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
 <AlertDialog open={!!restoreOpen} onOpenChange={v=>!v&&setRestoreOpen(null)}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Restaurar esta base?</AlertDialogTitle><AlertDialogDescription>Os dados atuais serão substituídos pela cópia selecionada. Exporte um backup antes se quiser preservar a base atual.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Cancelar</AlertDialogCancel><AlertDialogAction onClick={async()=>{if(restoreOpen&&await persist(restoreOpen,'Base restaurada.')){setConfig(restoreOpen.config);setRestoreOpen(null);setDay('0')}}}>Restaurar</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog>
 </SidebarProvider>;
}
